from make_notebooks import notebook
notebook('02_Прогноз_и_нейросеть.ipynb','Прогноз и демонстрационная нейросеть',[
('Что исследуем: один интерфейс для шести прогнозов. Отдельный синтетический сценарий с четырьмя неравномерно нагруженными Fog не подменяет базовый сценарий парковки.',"from efc.forecast.study import forecast_study\nfrom efc.forecast.views import plot_forecasts\nfrom efc.forecast.models import FrozenNetwork,state_of,to_ranks,mm1k\nimport pandas as pd,json\nmetrics,predictions,models,sim=forecast_study()\ndisplay(metrics)"),
('Входы обучения, калибровки и проверки разделены по времени завершения задач. На запрос доступны только ранее завершённые ответы; потерянные события не имеют целевой задержки и считаются отдельно.',"meta=json.loads(Path('results/forecast_metadata.json').read_text())\nprint(meta)\nassert meta['train_end_max_s']<meta['cut_train_s']\nassert meta['calibration_end_max_s']<meta['cut_test_s']\nassert (predictions.last_observed_completion_s<predictions.query_s).all()"),
('Схема показывает заменяемую «розетку». MAE и покрытие p95 — разные показатели: хорошая точечная ошибка не означает правильного хвоста; фактическое недопокрытие не скрывается.',"plot_forecasts(metrics,predictions)"),
('Файл my_network.py — пример адаптера для вашей сети. Сохранённые веса демонстрационного MLP проверяем отдельным вычислением без pickle; порядковые команды не подставляются вместо секунд.',"frozen=FrozenNetwork(json.loads(Path('results/demo_network.json').read_text()))\ns=state_of(next(r for r in sim['tasks'] if r['status']=='completed'))\na=frozen.predict(s);b=models['NeuralNet'].predict(s)\nassert abs(a['mean_ms']-b['mean_ms'])<1e-7\nprint(a)\nprint('Порядковый пример:',to_ranks({'F0':a,'F1':{'mean_ms':a['mean_ms']+1,'p95_ms':a['p95_ms']+1}}))"),
('Проверка: таблица для статьи читается из того же файла результатов. Queueing учитывает текущую очередь, M/M/1/K сохранён отдельно. Конформная поправка вычислена только по калибровке; зависимость во времени исключает безусловную гарантию95%. M/M/1/K — приближение; равенство Литтла проверяется внутри его предпосылок.',"q=mm1k(10,.055,51)\nassert abs(q['L']-q['lambda_eff']*q['W_s'])<1e-10\nfrom_file=pd.read_csv('results/forecast_metrics.csv')\nassert len(from_file)==6\nassert ((from_file.coverage_p95>=0)&(from_file.coverage_p95<=1)).all()\ndisplay(from_file[['method','mae_ms','coverage_before','coverage_p95']].rename(columns={'mae_ms':'MAE в статье = модели','coverage_p95':'покрытие в статье = модели'}))\nprint('OK')")])
